 * EventBus.publish(List<SObject>) exactly once. EventBus.publish returns a
 * List<Database.SaveResult> in the same order as the input list, so we still get a
 * SaveResult per Opportunity, in the original input order, without exceeding any
 * governor limits.
 */
public with sharing class DealEventPublisher {

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

