/**
 * Queueable job that creates CSAT survey Tasks for one or more Cases.
 *
 * Design notes / why this shape:
 * - The org can only enqueue up to 50 Queueable jobs in a single
 *   transaction (Limits.getLimitQueueableJobs()), and that limit applies
 *   whether the enqueue call happens synchronously (e.g. from a trigger)
 *   or from inside an already-executing Queueable. There is no safe way
 *   to call System.enqueueJob once per case when up to 200 cases can be
 *   closed in one bulk operation (list view mass-close, nightly API
 *   cleanup of up to 200 records).
 * - Chaining jobs (each job enqueueing the next one from inside
 *   execute()) was tried but hits "Maximum stack depth has been reached"
 *   once the chain gets long, because Apex enforces a maximum Queueable
 *   chain depth. Chaining 150+ jobs sequentially is not viable.
 * - The fix: batch the case Ids into groups of up to MAX_CASES_PER_JOB
 *   and enqueue at most MAX_ENQUEUE_PER_TRANSACTION jobs, each processing
 *   its own batch of cases. Within a job, each case is still handled
 *   independently inside a try/catch, so a DML failure on one case's
 *   Task (e.g. a validation rule) does not prevent Tasks from being
 *   created for the other cases in that job, or in any other job.
 * - With up to 200 cases and a batch size of 4, that's 50 jobs - exactly
 *   at the per-transaction enqueue limit, so this comfortably covers the
 *   stated "up to 200 at a time" nightly cleanup as well as large list
 *   view bulk closes, while leaving headroom via a configurable batch
 *   size if volumes grow further (the vendor integration mentioned).
 */
public with sharing class CaseSurveyJob implements Queueable {

    private static final Integer MAX_ENQUEUE_PER_TRANSACTION = 50;

    // Number of cases handled per queued job. With 200 cases this yields
    // exactly 50 jobs, staying within the per-transaction enqueue limit.
    private static final Integer MAX_CASES_PER_JOB = 4;

    private final List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this(new List<Id>{ caseId });
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = (caseIds != null) ? caseIds : new List<Id>();
    }

    /**
     * Entry point used by CaseTrigger. Splits the case Ids into batches
     * and enqueues one job per batch, staying within the per-transaction
     * limit of enqueued Queueable jobs.
     */
    public static void enqueueForCases(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<List<Id>> batches = new List<List<Id>>();
        List<Id> currentBatch = new List<Id>();

        for (Id caseId : caseIds) {
            currentBatch.add(caseId);
            if (currentBatch.size() == MAX_CASES_PER_JOB) {
                batches.add(currentBatch);
                currentBatch = new List<Id>();
            }
        }
        if (!currentBatch.isEmpty()) {
            batches.add(currentBatch);
        }

        Integer jobsToEnqueue = Math.min(batches.size(), MAX_ENQUEUE_PER_TRANSACTION);

        // If, for some reason, volumes exceed what batching can fit into
        // the enqueue limit (e.g. batch size reduced, or a much larger
        // bulk operation than documented), merge any overflow batches
        // into the last job rather than silently dropping cases.
        if (batches.size() > MAX_ENQUEUE_PER_TRANSACTION) {
            List<Id> mergedOverflow = new List<Id>();
            for (Integer i = MAX_ENQUEUE_PER_TRANSACTION - 1; i < batches.size(); i++) {
                mergedOverflow.addAll(batches[i]);
            }
            batches.set(MAX_ENQUEUE_PER_TRANSACTION - 1, mergedOverflow);
        }

        for (Integer i = 0; i < jobsToEnqueue; i++) {
            System.enqueueJob(new CaseSurveyJob(batches[i]));
        }
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Map<Id, Case> casesById = new Map<Id, Case>([
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
        ]);

        List<Task> tasksToInsert = new List<Task>();

        for (Id caseId : caseIds) {
            Case c = casesById.get(caseId);

            if (c == null) {
                continue;
            }

            // Defensive re-check: by the time this async job runs the
            // case could theoretically have been reopened or lost its
            // contact. Only build a survey task if conditions still hold.
            if (!c.IsClosed || c.ContactId == null) {
                continue;
            }

            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        // Partial success: allOrNone = false ensures a failure creating
        // one case's survey Task (e.g. a validation rule) does not stop
        // Tasks from being created for the other cases in this batch.
        List<Database.SaveResult> results = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey Task - ' + err.getMessage());
                }
            }
        }
    }
}
