        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        for (OpportunityContactRole ocr : existingRoles) {
            if (memberIdToContactId.containsKey(ocr.ContactId) && !existingRoleByContact.containsKey(ocr.ContactId)) {
                existingRoleByContact.put(ocr.ContactId, ocr);
            } else {
                // Duplicate role for same contact, or a role for a contact outside the household: remove it.
                rolesToDelete.add(ocr);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

